DO $$
BEGIN
  FOR i IN 0..99 LOOP
    EXECUTE format('CREATE TABLE customers_%s PARTITION OF customers FOR VALUES FROM (%s) TO (%s)', i, i * 10000000, (i + 1) * 10000000);
  END LOOP;
END $$;

